import 'package:flutter/material.dart';
class TrainingLibraryScreen extends StatelessWidget{const TrainingLibraryScreen({super.key});static const lessons=[('Reward marker basics','Pair a consistent marker with a reward in short, calm sessions.'),('Name response','Reward voluntary attention and keep practice brief.'),('Settle on a mat','Reward calm choices and allow the pet to move away.'),('Loose-leash foundations','Practice in a low-distraction area and reward slack leash.'),('Carrier comfort','Let the pet explore the carrier at their own pace; never force entry.')];@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Positive-reinforcement lessons')),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('Short, reward-based practice ideas. Adapt to your pet and stop if they show stress.'),const SizedBox(height:12),...lessons.map((e)=>Card(child:ListTile(leading:const Icon(Icons.school_outlined,color:Color(0xFF39845A)),title:Text(e.$1),subtitle:Text(e.$2))))]));}
